import numpy as np
import pandas as pd

def town_slopes(path='towns-temp.csv'):
    df = pd.read_csv(path)
    def one(g):
        n = len(g)
        if n < 3:
            return pd.Series({'slope': np.nan, 'intercept': np.nan, 'r2': np.nan, 'n': n})
        c = np.cov(g['day'], g['temp_c'])
        b = c[0, 1] / c[0, 0]
        a = g['temp_c'].mean() - b * g['day'].mean()
        r2 = c[0, 1] ** 2 / (c[0, 0] * c[1, 1])
        return pd.Series({'slope': b, 'intercept': a, 'r2': r2, 'n': n})
    return df.groupby('town').apply(one, include_groups=False)

